package com.bank;import java.time.*;import java.util.*;public class BankingService{final List<Customer>customers=new ArrayList<>();final List<BankAccount>accounts=new ArrayList<>();final List<Transaction>transactions=new ArrayList<>();int tx=1000;void add(Customer c){if(customers.stream().anyMatch(x->x.getCustomerId()==c.getCustomerId()))throw new IllegalArgumentException("Duplicate customer");customers.add(c);}void add(BankAccount a){customer(a.customerId);if(a.balance<a.minimum())throw new InsufficientBalanceException("Minimum opening balance Rs. "+a.minimum());accounts.add(a);}Customer customer(int id){return customers.stream().filter(x->x.getCustomerId()==id).findFirst().orElseThrow(()->new CustomerNotFoundException("Customer not found"));}BankAccount account(long no){return accounts.stream().filter(x->x.accountNumber==no).findFirst().orElseThrow(()->new InvalidAccountException("Account not found"));}void deposit(long no,double amount){valid(amount);BankAccount a=account(no);BankingOperation op=(x,b)->b+x;a.balance=op.execute(amount,a.balance);record(a,"DEPOSIT",amount,"Cash deposit");}void withdraw(long no,double amount){valid(amount);BankAccount a=account(no);BankingOperation op=(x,b)->b-x;double next=op.execute(amount,a.balance);if(next<a.minimum())throw new InsufficientBalanceException("Minimum balance Rs. "+a.minimum());a.balance=next;record(a,"WITHDRAW",amount,"Cash withdrawal");}void transfer(long from,long to,double amount){if(from==to)throw new InvalidTransactionException("Accounts must differ");valid(amount);BankAccount s=account(from),t=account(to);if(s.balance-amount<s.minimum())throw new InsufficientBalanceException("Insufficient balance");s.balance-=amount;t.balance+=amount;record(s,"TRANSFER",amount,"To "+to);record(t,"DEPOSIT",amount,"From "+from);}double interest(long no,double rate){BankAccount a=account(no);BankingOperation op=(r,b)->b*r/100;double x=op.execute(rate,a.balance);a.balance+=x;record(a,"INTEREST",x,"Interest");return x;}void record(BankAccount a,String type,double amount,String desc){transactions.add(new Transaction(++tx,a.accountNumber,type,amount,LocalDateTime.now(),desc));}void valid(double x){if(x<=0)throw new InvalidTransactionException("Amount must be positive");}}
